def source_date_range(df: pd.DataFrame, date_col: str = "date") -> str:
    if df.empty or date_col not in df.columns:
        return "-"
    dates = pd.to_datetime(df[date_col], errors="coerce").dropna()
    if dates.empty:
        return "-"
    return f"{dates.min().date()} - {dates.max().date()}"


