# BME visual semantics. Category colours remain stable across charts, while
# red/green are reserved for actual exceptions and favourable movement. A risk
# score is an investigation priority, so supplier colours must not imply a
# formal pass/fail decision.
BME_COLORS = {
    "primary": "#2855C5",
    "primary_dark": "#173B8F",
    "iqc": "#2F6BFF",
    "pqc": "#6B5CC5",
    "fqc": "#D98200",
    "machine": "#168A83",
    "alert": "#C83C55",
    "positive": "#168A5B",
    "neutral": "#667085",
    "control": "#475467",
    "grid": "#E7EAF0",
}
BME_GATE_COLORS = {
    "IQC": BME_COLORS["iqc"],
    "PQC": BME_COLORS["pqc"],
    "FQC": BME_COLORS["fqc"],
}
BME_SUPPLIER_COLORS = {
    "CMW": BME_COLORS["primary"],
    "FSD": "#148A83",
    "TEKTRO": "#A15C17",
}


def apply_bme_chart_style(fig: go.Figure, *, height: int | None = None, showlegend: bool | None = None) -> go.Figure:
    """Apply one restrained, readable chart system without changing data."""
    layout: dict[str, object] = {
        "paper_bgcolor": "rgba(0,0,0,0)",
        "plot_bgcolor": "#FFFFFF",
        "font": {"family": "Inter, PingFang SC, Microsoft YaHei, sans-serif", "size": 14, "color": "#475467"},
        "hoverlabel": {"align": "left", "font_size": 14},
    }
    if height is not None:
        layout["height"] = height
    if showlegend is not None:
        layout["showlegend"] = showlegend
    fig.update_layout(**layout)
    fig.update_xaxes(gridcolor=BME_COLORS["grid"], zerolinecolor=BME_COLORS["grid"], tickfont={"size": 13})
    fig.update_yaxes(gridcolor=BME_COLORS["grid"], zerolinecolor=BME_COLORS["grid"], tickfont={"size": 13})
    return fig


def bme_display_text(value: object) -> str:
    """Translate dashboard-generated BME labels without altering source data."""
    text = str(value or "")
    if st.session_state.get("lang") != "English":
        return text
    replacements = {
        "PQC 车型（未对应整车料号）": "PQC Model (not linked to whole-bike item)",
        "CMW 整车料号": "CMW Whole-bike Item Code",
        "IQC 来料零部件": "IQC Incoming Component",
        "整车料号 ": "Whole-bike Item Code ",
        "Model / 车型 ": "Model ",
        "料号 ": "Item Code ",
        "来料零部件": "Incoming Component",
        "车架 / 前叉": "Frame / Fork",
    }
    for source, translated in replacements.items():
        text = text.replace(source, translated)
    return text


